using System.Collections;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DoubleEffectsAction", menuName = "Data/Battle/Battle Actions/Enchantment Actions/Double Effect Action")]
public class DoubleEffectsAction : BattleAction
{
	[Header("Effects")]
	[SerializeField]
	private Effect[] actionDoubleEffects;

	[SerializeField]
	private bool enableNothingToDoubleEffectAction;

	[SerializeField]
	[ShowIf("enableNothingToDoubleEffectAction")]
	private DefaultEffectAction nothingToDoubleEffectAction;

	[SerializeField]
	[ShowIf("enableNothingToDoubleEffectAction")]
	private int nothingToDoubleEffectActionAmount;

	[SerializeField]
	private bool playerTarget;

	[SerializeField]
	private bool enemyTarget;

	[SerializeField]
	private bool fortify;

	[SerializeField]
	[ShowIf("fortify")]
	private Effect fortifyEffect;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	[SerializeField]
	private bool enableScreenShake;

	[SerializeField]
	[ShowIf("enableScreenShake")]
	private FloatFloatEvent OnScreenShake;

	[SerializeField]
	[ShowIf("enableScreenShake")]
	private float screenShakePower = 0.2f;

	[SerializeField]
	[ShowIf("enableScreenShake")]
	private float screenShakeDuration = 0.2f;

	[SerializeField]
	private bool disableGainingEffectVFXAndSFX;

	private int fortifyAmount;

	public DefaultEffectAction NothingToDoubleEffectAction => nothingToDoubleEffectAction;

	public int NothingToDoubleEffectActionAmount => nothingToDoubleEffectActionAmount;

	public bool PlayerTarget => playerTarget;

	public bool EnemyTarget => enemyTarget;

	public bool Fortify => fortify;

	public override void CastTarget(GameObject target, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastTargetVFXDelay(target, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		UnitEffects component = target.GetComponent<UnitEffects>();
		for (int i = 0; i < actionDoubleEffects.Length; i++)
		{
			int num = component.IsEffectActiveGetAmount(actionDoubleEffects[i], activateFeedback: false);
			if (num > 0)
			{
				bool flag = IsVFXEnabled();
				if (flag)
				{
					PlaySFX();
				}
				SpawnVFX(GetVFXOwnerPosition(target), 4f);
				if (disableGainingEffectVFXAndSFX)
				{
					component.AddEffect(actionDoubleEffects.First(), num, effectFeedback: true, callEffectsCallbacks: true, null, !flag);
				}
				else
				{
					component.AddEffect(actionDoubleEffects.First(), num);
				}
				if (fortify)
				{
					component.AddEffect(fortifyEffect, fortifyAmount);
				}
				if (enableScreenShake)
				{
					OnScreenShake.Raise(screenShakePower, screenShakeDuration);
				}
			}
			else if (enableNothingToDoubleEffectAction)
			{
				nothingToDoubleEffectAction.CastTargetAmount(target, nothingToDoubleEffectActionAmount, source);
				if (fortify)
				{
					component.AddEffect(fortifyEffect, fortifyAmount);
				}
			}
		}
		ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		fortifyAmount = amount;
		CastTarget(target, source);
	}

	private IEnumerator CastTargetVFXDelay(GameObject target, GameObject source)
	{
		UnitEffects unitEffects = target.GetComponent<UnitEffects>();
		for (int i = 0; i < actionDoubleEffects.Length; i++)
		{
			int effectAmount = unitEffects.IsEffectActiveGetAmount(actionDoubleEffects[i], activateFeedback: false);
			if (effectAmount > 0)
			{
				bool vfxEnabled = IsVFXEnabled();
				if (vfxEnabled)
				{
					PlaySFX();
				}
				SpawnVFX(GetVFXOwnerPosition(target), 4f);
				yield return new WaitForSeconds(vfxDelay);
				if (disableGainingEffectVFXAndSFX)
				{
					unitEffects.AddEffect(actionDoubleEffects.First(), effectAmount, effectFeedback: true, callEffectsCallbacks: true, null, !vfxEnabled);
				}
				else
				{
					unitEffects.AddEffect(actionDoubleEffects.First(), effectAmount);
				}
				if (fortify)
				{
					unitEffects.AddEffect(fortifyEffect, fortifyAmount);
				}
				if (enableScreenShake)
				{
					OnScreenShake.Raise(screenShakePower, screenShakeDuration);
				}
			}
			else if (enableNothingToDoubleEffectAction)
			{
				nothingToDoubleEffectAction.CastTargetAmount(target, nothingToDoubleEffectActionAmount, source);
				if (fortify)
				{
					unitEffects.AddEffect(fortifyEffect, fortifyAmount);
				}
			}
		}
	}
}
